42	export class Engine {
43	  private _scene: Scene;
44	  private _camera: THREE.PerspectiveCamera;
45	  private _cameraTarget: THREE.Object3D;
46	  private _cameraTargetFollow: THREE.Object3D | null = null;
47	  private _cameraTargetFollowAnchorNode: THREE.Object3D | null = null;
48	  private _cameraTargetFollowLocalAnchor: THREE.Vector3 | null = null;
49	  private _followBounds = new THREE.Box3();
50	  private _followCenter = new THREE.Vector3();
51	  private _followWorldPos = new THREE.Vector3();
52	  private _renderer: RendererLike | null = null;
53	  private _postProcessor: PostProcessor | null = null;
54	  private _backgroundManager: BackgroundManager | null = null;
55	  private _rendererBackend: RendererBackend = "webgl";
56	  private _loader: ModelLoader;
57	  private _animationLoop: AnimationLoop | null = null;
58	  private _lastDelta = 0;
59	  private _contextLost = false;
60	  private _onContextLost: ((event: Event) => void) | null = null;
61	  private _onContextRestored: ((event: Event) => void) | null = null;
62	  private _opts: EngineOptions;
63	  private _pixelRatioMax: number;
64	  private _renderBudget: Required<RenderBudgetOptions>;
65	  private _renderModeState = {
66	    skipActive: false,
67	    exceededFrames: 0,
68	    stableFrames: 0,
69	  };
70	  private _didWarnPostProcessingFallback = false;
71	  private readonly _defaultThreeConfig = getDefaultThreeConfig();
72	
73	  constructor(opts: EngineOptions = {}) {
74	    this._opts = opts;
75	    this._renderBudget = this._resolveRenderBudget(opts.renderBudget);
76	    const pr = opts.pixelRatioMax;
77	    this._pixelRatioMax =
78	      typeof pr === "number" && Number.isFinite(pr) && pr > 0
79	        ? pr
80	        : this._defaultThreeConfig.pixelRatioMax;
81	    const responsive = ResponsiveRuntime.getDefault().getSnapshot();
82	    const aspect = responsive.viewportWidth / responsive.viewportHeight;
83	    const cam = opts.camera ?? {};
84	    const fov = cam.fov ?? this._defaultThreeConfig.camera.fov;
85	    const near = cam.near ?? this._defaultThreeConfig.camera.near;
86	    const far = cam.far ?? this._defaultThreeConfig.camera.far;
87	    this._camera = new THREE.PerspectiveCamera(fov, aspect, near, far);
88	    this._camera.scale.set(1, 1, 1);
89	    this._camera.layers.enable(THREE_LAYER_EARTH);
90	    this._camera.layers.enable(THREE_LAYER_MARQUEE);
91	    this._camera.layers.enable(THREE_LAYER_ROCKET);
92	    if (cam.position) {
93	      this._camera.position.set(
94	        cam.position.x ?? 0,
95	        cam.position.y ?? 0,
96	        cam.position.z ?? 0,
97	      );
98	    }
99	    const sceneFactory = opts.dependencies?.sceneFactory;
100	    this._scene = sceneFactory ? (sceneFactory() as Scene) : new Scene();
101	    this._cameraTarget = new THREE.Object3D();
102	    this._cameraTarget.name = cameraTargetId;
103	    const ct = opts.cameraTarget?.position;
104	    this._cameraTarget.position.set(ct?.x ?? 0, ct?.y ?? 0, ct?.z ?? 0);
105	    const loaderFactory = opts.dependencies?.modelLoaderFactory;
106	    this._loader = loaderFactory
107	      ? (loaderFactory() as ModelLoader)
108	      : new ModelLoader();
109	  }
110	
111	  init(): boolean {
112	    const targetCanvas = this._resolveTargetCanvas();
113	    if (!targetCanvas) return false;
114	
115	    const scene = this._scene.three;
116	    scene.add(this._cameraTarget);
117	
118	    this._scene.registerObject(cameraId, this._camera);
119	    this._scene.registerObject(cameraTargetId, this._cameraTarget);
120	    const cfg = this._opts.scene ?? {};
121	    scene.background =
122	      cfg.background != null ? new THREE.Color(cfg.background) : null;
123	    const fogOpt = cfg.fog;
124	    scene.fog =
125	      fogOpt != null && typeof fogOpt === "object" && "far" in fogOpt
126	        ? new THREE.Fog(
127	            fogOpt.color ?? 0x000000,
128	            fogOpt.near ?? 1000,
129	            fogOpt.far ?? 15000,
130	          )
131	        : null;
132	
133	    const rendererOpts = this._opts.renderer ?? {};
134	    this._renderer = this._createRenderer(targetCanvas, rendererOpts);
135	    if (!this._renderer) return false;
136	    const responsive = ResponsiveRuntime.getDefault().getSnapshot();
137	    const w = responsive.viewportWidth;
138	    const h = responsive.viewportHeight;
139	    this._renderer.setSize?.(w, h);
140	    this._renderer.setPixelRatio?.(Math.min(responsive.render.clampedPixelRatio, this._pixelRatioMax));
141	    if (
142	      this._renderer &&
143	      hasWebGLRendererFeatures(this._renderer) &&
144	      this._renderer.shadowMap
145	    ) {
146	      const shadowOpt = this._opts.shadowMap ?? {};
147	      this._renderer.shadowMap.enabled = shadowOpt.enabled ?? false;
148	      this._renderer.shadowMap.type = shadowOpt.type ?? THREE.PCFSoftShadowMap;
149	    }
150	    this._renderer.toneMapping = THREE.ACESFilmicToneMapping;
151	    this._renderer.toneMappingExposure = 0.56;
152	    this._renderer.outputColorSpace = THREE.SRGBColorSpace;
153	    this._attachContextEvents();
154	
155	    this._camera.aspect = w / h;
156	    this._camera.updateProjectionMatrix();
157	
158	    const postProcessorOptions = this._resolvePostProcessorOptions();
159	    this._postProcessor =
160	      this._rendererBackend === "webgl" &&
161	      this._renderer instanceof THREE.WebGLRenderer &&
162	      postProcessorOptions
163	        ? new PostProcessor(
164	            this._renderer,
165	            scene,
166	            this._camera,
167	            postProcessorOptions,
168	          )
169	        : null;
170	
171	    const loadModel = (path: string) => this._loadModel(path);
172	    const loadModelWithAnimation = (path: string) =>
173	      this._loader.loadGLTF(this._scene.three, path, {
174	        addToScene: false,
175	      });
176	    const loadTexture = (path: string) => this._loader.loadTexture(path);
177	    const loadHdrTexture = (path: string) => this._loader.loadHdrTexture(path);
178	    const compileScene = (camera?: THREE.Camera) =>
179	      this._compileScene(camera ?? this._camera);
180	    const prepareTexture = (texture: THREE.Texture) =>
181	      this._prepareTexture(texture);
182	    const getObject = (id: string) => this._scene.getObject(id);
183	    const registerObject = (
184	      id: string,
185	      object: THREE.Object3D | Record<string, unknown>,
186	    ) => this._scene.registerObject(id, object);
187	    const unregisterObject = (id: string) => this._scene.unregisterObject(id);
188	    this._scene.setContext({
189	      scene: this._scene.three,
190	      camera: this._camera,
191	      renderer: this._renderer,
192	      rendererBackend: this._rendererBackend,
193	      compileScene,
194	      prepareTexture,
195	      getObject,
196	      registerObject,
197	      unregisterObject,
198	      loadModel,
199	      loadModelWithAnimation,
200	      loadTexture,
201	      loadHdrTexture,
202	    });
203	    if (this._renderer instanceof THREE.WebGLRenderer) {
204	      this._backgroundManager = new BackgroundManager(
205	        this._renderer,
206	        this._scene.three,
207	        this._camera,
208	      );
209	      this._scene.registerObject(
210	        "env.backgroundManager.runtime",
211	        this._backgroundManager as unknown as Record<string, unknown>,
212	      );
213	    }
214	    return true;
215	  }
