1090	  private _staggerContactBlocks(
1091	    blocks: readonly HTMLElement[],
1092	    visible: boolean,
1093	  ): void {
1094	    blocks.forEach((block, index) => {
1095	      const timerId = window.setTimeout(() => {
1096	        if (visible) {
1097	          block.classList.remove("is-block-reveal-down");
1098	          BlockReveal.reveal(block);
1099	          return;
1100	        }
1101	        block.classList.add(INIT_DOM_CLASSES.blockBase);
1102	        block.classList.remove(INIT_DOM_CLASSES.blockUp);
1103	        block.classList.remove(BLOCK_HIDDEN_CLASS, INIT_DOM_CLASSES.boxHidden);
1104	        void block.getBoundingClientRect();
1105	        block.classList.add("is-block-reveal-down");
1106	      }, index * CONTACT_REVEAL_STAGGER_MS);
1107	      this._contactMotionTimerIds.push(timerId);
1108	    });
1109	  }
