1	import type { Engine } from "../core/Engine.js";
2	import { BackgroundMaterialRuntime } from "../runtime/BackgroundMaterialRuntime.js";
3	import { Helpers } from "../utils/Helpers.js";
4	import type {
5	  BackgroundRuntimePort,
6	  BackgroundTransitionMode,
7	  BackgroundVariantKey,
8	} from "../types/object-runtime.types.js";
9	import type {
10	  SceneBackgroundPolicy,
11	  SceneBackgroundState,
12	} from "../types/runtime.types.js";
13	
14	export class BackgroundController {
15	  private static readonly _CLASS = "BackgroundController";
16	  private _engine: Engine | null = null;
17	  private readonly _lastSheetIdByBackgroundId = new Map<string, string | null>();
18	  private readonly _lastStateByBackgroundId = new Map<string, SceneBackgroundState>();
19	  private _transitionEnabled = true;
20	
21	  bind(engine: Engine): void {
22	    this._engine = engine;
23	  }
24	
25	  setTransitionEnabled(enabled: boolean): void {
26	    this._transitionEnabled = enabled;
27	  }
28	
29	  dispose(): void {
30	    this._engine = null;
31	    this._lastSheetIdByBackgroundId.clear();
32	    this._lastStateByBackgroundId.clear();
33	    this._transitionEnabled = true;
34	  }
35	
36	  sync<TSceneKey extends string, TSheetId extends string>(
37	    sceneKey: TSceneKey,
38	    progress: number,
39	    sheetId: TSheetId | null,
40	    policy: SceneBackgroundPolicy<TSceneKey, TSheetId> | null,
41	  ): void {
42	    if (!policy) return;
43	    const runtime = this._getBackgroundRuntime(policy.backgroundId);
44	    if (!runtime) return;
45	
46	    const state = this._resolveState(sceneKey, progress, sheetId, policy);
47	    const lastState = this._lastStateByBackgroundId.get(policy.backgroundId) ?? null;
48	    const lastSheetId =
49	      this._lastSheetIdByBackgroundId.get(policy.backgroundId) ?? null;
50	    const didStateChange = !this._isSameState(lastState, state);
51	
52	    if (didStateChange) {
53	      runtime.setRuntimeState({
54	        look: state.look ? { ...state.look } : undefined,
55	        variant: state.variant,
56	      });
57	    }
58	
59	    this._resetShaderClockOnEntry(
60	      policy.backgroundId,
61	      lastState?.variant ?? null,
62	      state.variant,
63	      policy.resetShaderClockOnVariant ?? null,
64	    );
65	    if (didStateChange) {
66	      this._startTransitionOnChange(
67	        policy.backgroundId,
68	        lastSheetId,
69	        sheetId,
70	        this._resolveTransitionMode(lastSheetId, sheetId, policy),
71	      );
72	    }
73	    this._logSheetChange(policy.backgroundId, sceneKey, progress, lastSheetId, sheetId, state);
74	    this._lastSheetIdByBackgroundId.set(policy.backgroundId, sheetId);
75	    this._lastStateByBackgroundId.set(policy.backgroundId, this._cloneState(state));
76	  }
77	
78	  private _resolveState<TSceneKey extends string, TSheetId extends string>(
79	    sceneKey: TSceneKey,
80	    progress: number,
81	    sheetId: TSheetId | null,
82	    policy: SceneBackgroundPolicy<TSceneKey, TSheetId>,
83	  ): SceneBackgroundState {
84	    const baseState = this._resolveBaseState(sceneKey, sheetId, policy);
85	    if (!policy.resolveState) {
86	      return this._cloneState(baseState);
87	    }
88	
89	    const resolvedState = policy.resolveState(
90	      {
91	        sceneKey,
92	        progress: Helpers.clamp01(progress),
93	        sheetId,
94	      },
95	      this._cloneState(baseState),
96	    );
97	    return this._cloneState(resolvedState);
98	  }
99	
100	  private _resolveTransitionMode<TSheetId extends string>(
101	    previousKey: string | null,
102	    nextKey: string | null,
103	    policy: SceneBackgroundPolicy<string, TSheetId>,
104	  ): BackgroundTransitionMode {
105	    if (!previousKey || !nextKey) return "crossfade";
106	    const matchedRule = policy.transitionRules?.find((rule) => {
107	      return rule.from === previousKey && rule.to === nextKey;
108	    });
109	    return matchedRule?.mode ?? "crossfade";
110	  }
111	
112	  private _resolveBaseState<TSceneKey extends string, TSheetId extends string>(
113	    sceneKey: TSceneKey,
114	    sheetId: TSheetId | null,
115	    policy: SceneBackgroundPolicy<TSceneKey, TSheetId>,
116	  ): SceneBackgroundState {
117	    const sceneState = policy.statesBySceneKey?.[sceneKey];
118	    if (sceneState) {
119	      return this._cloneState(sceneState);
120	    }
121	    if (!sheetId) {
122	      return this._cloneState(policy.defaultState);
123	    }
124	    return this._cloneState(
125	      policy.statesBySheetId?.[sheetId] ?? policy.defaultState,
126	    );
127	  }
128	
129	  private _cloneState(
130	    state: Readonly<SceneBackgroundState>,
131	  ): SceneBackgroundState {
132	    return {
133	      variant: state.variant,
134	      look: state.look ? { ...state.look } : undefined,
135	    };
136	  }
137	
138	  private _startTransitionOnChange(
139	    backgroundId: string,
140	    previousKey: string | null,
141	    nextKey: string | null,
142	    mode: BackgroundTransitionMode,
143	  ): void {
144	    if (!this._transitionEnabled) return;
145	    if (!previousKey || !nextKey || previousKey === nextKey) {
146	      return;
147	    }
148	    if (mode === "skip") return;
149	    this._engine?.getBackgroundManager()?.startTransition(backgroundId);
150	  }
151	
152	  private _resetShaderClockOnEntry(
153	    backgroundId: string,
154	    previousVariant: BackgroundVariantKey | null,
155	    nextVariant: BackgroundVariantKey,
156	    resetVariant: BackgroundVariantKey | null,
157	  ): void {
158	    if (!resetVariant) return;
159	    if (nextVariant !== resetVariant) return;
160	    if (previousVariant === nextVariant) return;
161	    this._engine?.getBackgroundManager()?.resetShaderClock(backgroundId);
162	  }
163	
164	  private _getBackgroundRuntime(id: string): BackgroundRuntimePort | null {
165	    return this._engine?.getSceneObjectById(id) as BackgroundRuntimePort | null;
166	  }
167	
168	  private _logSheetChange(
169	    backgroundId: string,
170	    sceneKey: string,
171	    progress: number,
172	    previousSheetId: string | null,
173	    nextSheetId: string | null,
174	    state: SceneBackgroundState,
175	  ): void {
176	    if (previousSheetId === nextSheetId) return;
177	  }
178	
179	  private _isSameState(
180	    previousState: SceneBackgroundState | null,
181	    nextState: SceneBackgroundState,
182	  ): boolean {
183	    if (!previousState) return false;
184	    if (previousState.variant !== nextState.variant) return false;
185	    return this._isSameLook(previousState.look, nextState.look);
186	  }
187	
188	  private _isSameLook(
189	    previousLook: SceneBackgroundState["look"],
190	    nextLook: SceneBackgroundState["look"],
191	  ): boolean {
192	    if (!previousLook && !nextLook) return true;
193	    if (!previousLook || !nextLook) return false;
194	    return (
195	      previousLook.topColor === nextLook.topColor &&
196	      previousLook.bottomColor === nextLook.bottomColor &&
197	      previousLook.accentColor === nextLook.accentColor &&
198	      previousLook.starIntensity === nextLook.starIntensity &&
199	      previousLook.starDensity === nextLook.starDensity &&
200	      previousLook.nebulaStrength === nextLook.nebulaStrength &&
201	      previousLook.motionStrength === nextLook.motionStrength &&
202	      previousLook.legacyMix === nextLook.legacyMix
203	    );
204	  }
205	}
